const CHECKOUT = {
  starter: "https://pay.hotmart.com/C108044953A?checkoutMode=10&bid=1792089939795",   // <- paste Starter ($29) payment link here
  premium: "https://pay.hotmart.com/C108044953A?off=758kpgid"    // <- paste Premium ($47) payment link here
};
// TESTIMONIALS: add ONLY real quotes from real customers (with their permission).
// The section stays hidden until at least one entry exists.
// Example: {quote:"...", name:"First name L.", role:"Reader since 2026"}
const TESTIMONIALS = [];
document.querySelectorAll('[data-plan]').forEach(function(a){
  var url = CHECKOUT[a.dataset.plan];
  if(url){ a.href = url; a.target = "_blank"; a.rel = "noopener"; }
  else if(a.getAttribute('href') === '#'){ a.href = '#plans'; }
});

(function(){
  if(!TESTIMONIALS.length) return;
  var g=document.getElementById('tg');
  TESTIMONIALS.forEach(function(x){
    var d=document.createElement('div');d.className='tc';
    var s=document.createElement('div');s.className='stars';s.textContent='★★★★★';
    var p=document.createElement('p');p.textContent='\u201C'+x.quote+'\u201D';
    var f=document.createElement('footer');var b=document.createElement('b');b.textContent=x.name;var r=document.createElement('span');r.textContent=x.role||'';
    f.appendChild(b);f.appendChild(r);d.appendChild(s);d.appendChild(p);d.appendChild(f);g.appendChild(d);
  });
  document.getElementById('testimonials').hidden=false;
  var li=document.querySelector('nav ul li:nth-child(4)');
  if(li){var n=document.createElement('li');n.innerHTML='<a href="#testimonials">Testimonials</a>';li.parentNode.insertBefore(n,li);}
})();
